CREATE TABLE guilds (id text PRIMARY KEY, config jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE members (id uuid PRIMARY KEY, guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, discord_id text NOT NULL, display_name text NOT NULL, active boolean NOT NULL DEFAULT true, pending_name text, pending_platform text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(guild_id,discord_id));
CREATE TABLE identities (guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, primary_id text NOT NULL, member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, current_name text NOT NULL, verified boolean NOT NULL DEFAULT false, last_seen_at timestamptz, PRIMARY KEY(guild_id,primary_id));
CREATE TABLE name_history (guild_id text NOT NULL, primary_id text NOT NULL, name text NOT NULL, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, PRIMARY KEY(guild_id,primary_id,name), FOREIGN KEY(guild_id,primary_id) REFERENCES identities(guild_id,primary_id) ON DELETE CASCADE);
CREATE TABLE pairing_codes (hash text PRIMARY KEY, guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE collectors (id uuid PRIMARY KEY, guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, name text NOT NULL, token_hash text UNIQUE NOT NULL, revoked boolean NOT NULL DEFAULT false, last_seen_at timestamptz, status jsonb NOT NULL DEFAULT '{}');
CREATE TABLE matches (id uuid PRIMARY KEY, guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, guid text NOT NULL, state jsonb NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), calculation_version integer NOT NULL DEFAULT 1, UNIQUE(guild_id,guid));
CREATE INDEX matches_time ON matches(guild_id,started_at);
CREATE TABLE match_sources (match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, collector_id uuid NOT NULL REFERENCES collectors(id) ON DELETE CASCADE, PRIMARY KEY(match_id,collector_id));
CREATE TABLE receipts (collector_id uuid NOT NULL REFERENCES collectors(id) ON DELETE CASCADE, event_id uuid NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(collector_id,event_id));
CREATE TABLE match_members (match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, primary_id text NOT NULL, name text NOT NULL, team integer NOT NULL, stats jsonb NOT NULL, PRIMARY KEY(match_id,member_id,primary_id));
CREATE TABLE match_events (id uuid PRIMARY KEY, match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, fingerprint text NOT NULL, ordinal integer NOT NULL, type text NOT NULL, data jsonb NOT NULL, occurred_at timestamptz NOT NULL, UNIQUE(match_id,fingerprint,ordinal));
CREATE TABLE rating_snapshots (id uuid PRIMARY KEY, member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, playlist_id integer NOT NULL, mmr numeric NOT NULL, rank text, division text, source text NOT NULL, confidence text NOT NULL, measured_at timestamptz NOT NULL, UNIQUE(member_id,playlist_id,source,measured_at));
CREATE TABLE manual_records (id uuid PRIMARY KEY, guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, category text NOT NULL, value numeric NOT NULL, unit text NOT NULL, evidence text, description text, status text NOT NULL DEFAULT 'pending', reviewer text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE achievements (member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, key text NOT NULL, awarded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(member_id,key));
CREATE TABLE discord_messages (guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, key text NOT NULL, channel_id text NOT NULL, message_id text NOT NULL, PRIMARY KEY(guild_id,key));
CREATE TABLE notifications (id uuid PRIMARY KEY, guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, key text NOT NULL, kind text NOT NULL, payload jsonb NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, sent_at timestamptz, UNIQUE(guild_id,key));
CREATE TABLE audit_log (id uuid PRIMARY KEY, guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, actor text NOT NULL, action text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE web_sessions (hash text PRIMARY KEY, user_id text NOT NULL, guilds jsonb NOT NULL, expires_at timestamptz NOT NULL);
